SELECT count(DISTINCT p.mint) FILTER (WHERE h.recorded_at <= p.t + interval '60 s') AS ate_60s,
       count(DISTINCT p.mint) FILTER (WHERE h.recorded_at <= p.t + interval '120 s') AS ate_120s,
       count(DISTINCT p.mint) FILTER (WHERE h.recorded_at <= p.t + interval '180 s') AS ate_180s,
       (SELECT count(*) FROM p) AS primeiras
FROM p JOIN meme_token_state_history h ON h.mint = p.mint
 AND h.column_name IN ('completed_at', 'migrated_at') AND h.new_value IS NOT NULL
 AND h.recorded_at > p.c;
